async function h(i,o,s){const t=s?.chunkSize??100,e=s?.maxRounds??200;if(!Number.isInteger(t)||t<1||!Number.isInteger(e)||e<1)throw new Error("分页大小与计数上限必须为正整数");let n=0,r=0;for(let u=0;u<e;u+=1){const c=await i({...o,skip:r,limit:t}),a=Array.isArray(c)?c.length:0;if(n+=a,a<t)return n;r+=t}if((await i({...o,skip:r,limit:1})).length===0)return n;throw new Error(`计数未完成：已达到 ${e} 页上限，请缩小查询范围`)}export{h as c};
